const fs=require('fs');
const p='public/index.html';
let s=fs.readFileSync(p,'utf8');
const jump='    <button class="move-btn jump-pad" id="jumpPadBtn" aria-label="Pular"><span>⇧</span></button>\n';
if((s.match(/id="jumpPadBtn"/g)||[]).length!==1) throw new Error('jumpPadBtn occurrence mismatch');
if(!s.includes(jump)) throw new Error('jump button line not found');
s=s.replace(jump,'');
const anchor='    <button class="move-btn back" id="moveBackBtn" aria-label="Andar para trás">▼</button>\n  </div>\n';
if(!s.includes(anchor)) throw new Error('dpad closing anchor not found');
s=s.replace(anchor,anchor+'  <button class="move-btn jump-pad" id="jumpPadBtn" aria-label="Pular"><span>⇧</span></button>\n');
const cssAnchor='  #mobile #dpad .jump-pad span{font-size:17px!important;line-height:1!important}\n';
if(!s.includes(cssAnchor)) throw new Error('critical CSS anchor not found');
const jumpCss=`  #mobile #dpad .jump-pad span{font-size:17px!important;line-height:1!important}\n  #mobile #jumpPadBtn{position:fixed!important;right:18px!important;left:auto!important;bottom:18px!important;top:auto!important;width:48px!important;height:48px!important;min-width:48px!important;max-width:48px!important;min-height:48px!important;max-height:48px!important;margin:0!important;padding:0!important;display:flex!important;align-items:center!important;justify-content:center!important;pointer-events:auto!important;touch-action:none!important;z-index:110!important;border-radius:4px!important;background:rgba(103,124,96,.86)!important;border-top:2px solid rgba(190,210,178,.92)!important;border-left:2px solid rgba(190,210,178,.92)!important;border-right:2px solid rgba(37,52,36,.96)!important;border-bottom:2px solid rgba(37,52,36,.96)!important;box-shadow:0 0 0 1px rgba(20,29,20,.72)!important;color:#eef5e9!important;font:900 18px/1 Arial,sans-serif!important;text-align:center!important}\n  #mobile #jumpPadBtn span{font-size:20px!important;line-height:1!important;pointer-events:none!important}\n  #mobile #jumpPadBtn.touch-active,#mobile #jumpPadBtn:active{transform:translateY(1px)!important;background:rgba(145,166,136,.96)!important}\n  body.mobile-left-handed #mobile #jumpPadBtn{right:auto!important;left:18px!important}\n`;
s=s.replace(cssAnchor,jumpCss);
const landscapeAnchor='  body.mobile-left-handed #mobile #dpad{left:auto!important;right:8px!important}\n';
if(!s.includes(landscapeAnchor)) throw new Error('landscape anchor not found');
s=s.replace(landscapeAnchor,landscapeAnchor+'  #mobile #jumpPadBtn{right:12px!important;bottom:12px!important;width:42px!important;height:42px!important;min-width:42px!important;max-width:42px!important;min-height:42px!important;max-height:42px!important}\n  body.mobile-left-handed #mobile #jumpPadBtn{right:auto!important;left:12px!important}\n');
fs.writeFileSync(p,s);
console.log('Mobile jump button moved to opposite side');
